ForeverGuides.ProfessionData["first-aid"] = {
  alternatives={
    {from=1,note={de="Statt der Leinenverbände braut ihr rund 81 Schwache Heiltränke aus Friedensblume, Milden Gewürzen und Leeren Phiolen. Das Rezept lehrt der Erste-Hilfe-Lehrer, ab Skill 55 wird es gelb. Es ersetzt beide Leinenstufen, die Materialien also nicht addieren.",en="Instead of linen bandages, brew about 81 minor healing potions from peacebloom, mild spices and empty vials. The first aid trainer teaches the recipe and it turns yellow at skill 55. It replaces both linen steps, so do not add the materials."},steps={{crafts=81,from=1,mats={{3371,1},{2678,1},{2447,1}},rank="apprentice",res={de="Schwacher Heiltrank: stellt sofort etwas Gesundheit wieder her.",en="Minor healing potion: restores a little health instantly."},spell=1244431,src="trainer",to=75}},title={de="Schwache Heiltränke statt Leinen",en="Minor healing potions instead of linen"},to=75},
    {from=75,note={de="Sind Wollstoff und Verbände teuer, skillt ihr mit Geringen Heiltränken, wenigen Wollverbänden und Heiltränken weiter.",en="If wool cloth and bandages are expensive, keep skilling with lesser healing potions, a few wool bandages and healing potions."},steps={{crafts=29,from=75,mats={{3371,1},{2678,2},{2450,1}},rank="journeyman",res={de="Heiltrank, der sofort 140–180 Gesundheit heilt; teilt die Abklingzeit mit anderen Heiltränken.",en="A potion that heals 140–180 health instantly; it shares its cooldown with other healing potions."},spell=1244432,src="trainer",to=100},{crafts=15,from=100,mats={{2592,1}},rank="journeyman",res={de="Verband mit stärkerer Heilung als die Leinenstufe.",en="A bandage that heals more than the linen tier."},spell=3277,src="trainer",to=110},{crafts=44,from=110,mats={{3372,1},{2692,1},{2453,1}},rank="journeyman",res={de="Heiltrank, der sofort 280–360 Gesundheit heilt; 2 Minuten Trank-Abklingzeit.",en="A potion that heals 280–360 health instantly; 2 minute potion cooldown."},spell=1244433,src="trainer",to=150}},title={de="Kräuter und Heiltränke statt Wollverbände",en="Herbs and healing potions instead of wool bandages"},to=150},
    {from=155,note={de="Mit dem Handbuch für den Großen Heiltrank spart ihr Seidenstoff: rund 25 Tränke aus Lebenswurz, Scharfen Gewürzen und Verbleiten Phiolen. Benutzt das Handbuch vor der Herstellung. Der Trank ist bis 175 orange, danach gelb, plant also ein paar Versuche mehr ein.",en="With the greater healing potion manual you save silk cloth: about 25 potions from liferoot, hot spices and leaded vials. Use the manual before crafting. The potion is orange up to 175 and yellow after that, so plan a few extra attempts."},steps={{crafts=25,from=155,mats={{3372,1},{2692,3},{3357,1}},pat=255723,rank="expert",res={de="Großer Heiltrank: stellt sofort Gesundheit wieder her, Wirkung im Tooltip.",en="Greater healing potion: restores health instantly, effect in the tooltip."},spell=1244434,src="item",to=180}},title={de="Großer Heiltrank statt Seidenverbände",en="Greater healing potions instead of silk bandages"},to=180},
    {from=210,note={de="Für die ersten fünf Punkte ab 210 reichen rund 14 Schwere Seidenverbände aus 28 Seidenstoff. Das Rezept ist hier schon grün, die Zahl kann stark schwanken.",en="For the first five points from 210, about 14 heavy silk bandages from 28 silk cloth are enough. The recipe is already green here, so the count can vary a lot."},steps={{crafts=14,from=210,mats={{4306,2}},npcs={{f="A",loc="Arathi Highlands, Stromgarde Keep",locDe="Arathihochland, Burg Stromgarde",mapId=1417,n="Deneb Walker",x=27,y=58.8,zone={de="Arathihochland",en="Arathi Highlands"}},{f="H",loc="Dustwallow Marsh, Brackenwall Village",locDe="Düstermarschen, Brackenwall",mapId=1445,n="Balai Lok’Wein",x=36.4,y=30.4,zone={de="Düstermarschen",en="Dustwallow Marsh"}}},pat=16112,rank="expert",res={de="Heilt bis zu 640 Gesundheit über 8 Sekunden.",en="Heals up to 640 health over 8 seconds."},spell=7929,src="item",to=215}},title={de="Seide statt Magiestoff",en="Silk instead of mageweave"},to=215},
    {from=215,note={de="Habt ihr das Handbuch für den Überragenden Heiltrank, braut ihr 10 Tränke aus Sonnengras, Beruhigenden Gewürzen und Kristallphiolen. Sie bleiben bis 230 orange. Mit dem Handbuch für das Starke Gegengift lässt sich ab 215 ebenfalls skillen; kauft Materialien erst, wenn es vorliegt.",en="With the superior healing potion manual, brew 10 potions from sungrass, soothing spices and crystal vials. They stay orange until 230. The potent anti-venom manual also allows skilling from 215; buy materials only once you own it."},steps={{crafts=10,from=215,mats={{8925,1},{3713,1},{8838,1}},pat=255725,rank="expert",res={de="Überragender Heiltrank: stellt sofort Gesundheit wieder her, Wirkung im Tooltip.",en="Superior healing potion: restores health instantly, effect in the tooltip."},spell=1244435,src="item",to=225}},title={de="Überragender Heiltrank",en="Superior healing potions"},to=225},
    {from=260,note={de="Wer das Handbuch für den Erheblichen Heiltrank sparen will, bleibt bei Runenstoff: Runenstoffverbände bis 290, danach Schwere Runenstoffverbände. Beide lernt ihr beim Fraktionsarzt, bei 260 und bei 290.",en="To skip buying the major healing potion manual, stay with runecloth: runecloth bandages up to 290, then heavy runecloth bandages. You learn both from the faction doctor, at 260 and at 290."},steps={{crafts=50,from=260,mats={{14047,1}},rank="artisan",res={de="Heilt über 8 Sekunden.",en="Heals over 8 seconds."},spell=18629,src="trainer",to=290},{crafts=15,from=290,mats={{14047,2}},rank="artisan",res={de="Der stärkste klassische Verband der Strecke 1–300.",en="The strongest classic bandage of the 1–300 route."},spell=18630,src="trainer",to=300}},title={de="Runenstoffverbände bis 300",en="Runecloth bandages up to 300"},to=300},
  },
  intro={de="Eine Verbandsroute von 1 bis 300 mit zwei Trank-Abschnitten. Die Herstellzahlen sind Richtwerte: Sobald ein Rezept gelb wird, bleibt mancher Versuch ohne Punkt. Zwei Hürden: Den Expertenrang kauft ihr als Buch, den Fachmannrang schaltet eine Quest beim Arzt frei.",en="A bandage route from 1 to 300 with two potion sections. Craft counts are estimates: once a recipe turns yellow, some attempts give no point. Two gates: you buy the Expert rank as a book, and a quest with the doctor unlocks Artisan."},
